const deep = (root, sel) => { let r=[...root.querySelectorAll(sel)]; root.querySelectorAll('*').forEach(e=>{ if(e.shadowRoot) r=r.concat(deep(e.shadowRoot, sel)); }); return r; };
const out={};
out.customEls = [...new Set([...document.querySelectorAll('*')].filter(e=>e.tagName.includes('-')).map(e=>e.tagName.toLowerCase()))];
const bc = deep(document, 'a[href="/portal-mpa"]')[0];
out.bc = bc ? bc.closest('ul,ol,nav,div')?.outerHTML.slice(0,1200) : null;
out.bcHost = bc ? bc.getRootNode().host?.tagName : null;
const hdr = deep(document,'header')[0];
out.header = hdr?.outerHTML.slice(0,2500);
out.headerHost = hdr?.getRootNode().host?.outerHTML.slice(0,300);
out.imgs = deep(document,'img').map(i=>({alt:i.getAttribute('alt'), src:i.src.slice(-60)}));
return out;
}"}

